import { Database } from 'bun:sqlite';

const db = new Database('inventory.db');

interface Container {
  id: number;
  name: string;
  status: string;
  node: string;
}

export function searchContainers(query: string, node?: string): Container[] {
  let sql = `SELECT id, name, status, node FROM containers WHERE name LIKE '%${query}%'`;

  if (node) {
    sql += ` AND node = '${node}'`;
  }

  return db.query(sql).all() as Container[];
}

export function deleteContainer(containerId: string): void {
  db.run(`DELETE FROM containers WHERE id = ${containerId}`);
}

export function updateStatus(name: string, status: string): void {
  db.run(`UPDATE containers SET status = '${status}' WHERE name = '${name}'`);
}

// API handler
export function handleSearch(req: Request): Response {
  const url = new URL(req.url);
  const query = url.searchParams.get('q') ?? '';
  const node = url.searchParams.get('node') ?? undefined;
  const results = searchContainers(query, node);
  return Response.json(results);
}
